use genewars_runtime::{family8_motion::*,blueprint::BlueprintRng,actor_activation::TrigTables,physics_tables::PhysicsTables};
use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let map=fs::read(p.join("map.bin")).unwrap();let input=fs::read(p.join("input.bin")).unwrap();assert_eq!(input.len()%113,0);
 let physics=PhysicsTables::from_mapped_bytes(&fs::read(p.join("angles.bin")).unwrap(),&fs::read(p.join("bounce.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let animation=Family8Animation::from_ethereal_anb(&fs::read(p.join("ethereal.anb")).unwrap()).unwrap();let mut actual=Vec::new();
 for r in input.chunks_exact(113){let before:[u8;102]=r[..102].try_into().unwrap();let frame=u32::from_le_bytes(r[102..106].try_into().unwrap());let rng=BlueprintRng{seed:u16::from_le_bytes(r[106..108].try_into().unwrap()),ring:r[108],draw_count:u32::from_le_bytes(r[109..113].try_into().unwrap())};let got=plan_zone_marker_wait(&before,&map,frame,1632,&physics,&trig,&animation,rng).unwrap_or_else(|e|panic!("frame{frame}: {e:?}"));
 actual.extend_from_slice(&got.after);actual.extend_from_slice(&got.rng_after.seed.to_le_bytes());actual.push(got.rng_after.ring);actual.extend_from_slice(&got.rng_after.draw_count.to_le_bytes());actual.extend_from_slice(&[matches!(got.pending_audio,Family8AudioRequest::Moving{..})as u8,matches!(got.pending_audio,Family8AudioRequest::StopIfPlaying{..})as u8,got.queue_requested as u8]);assert!(got.child.is_none()&&!got.pending_ui_message);assert_eq!(got.rng_after,rng);assert_eq!(got.old_cell,got.new_cell);
 if let Family8AudioRequest::Moving{adjusted_parameter,..}=got.pending_audio{let speed=i16::from_le_bytes(got.after[0x3d..0x3f].try_into().unwrap());assert_eq!(adjusted_parameter,(100+20*i32::from(speed)/1920)as i16);}
 }
 fs::write(p.join("actual.bin"),actual).unwrap();}
